cd /app && echo "=== prune ===" && python -m bandit --prune-cache 0 --cache-dir /tmp/cachetest/.cache 2>&1; echo "exit=$?"; python -m bandit --cache-summary --cache-dir /tmp/cachetest/.cache 2>/dev/null
echo "=== size limit ===" && rm -rf /tmp/cachetest/.cache && python -m bandit /tmp/cachetest/foo.py --incremental --cache-dir /tmp/cachetest/.cache --cache-size-limit 1000 -f json 2>/dev/null >/dev/null; python -m bandit --cache-stats --cache-dir /tmp/cachetest/.cache 2>/dev/null
echo "=== corrupted cache ===" && rm -rf /tmp/cachetest/.cache && python -m bandit /tmp/cachetest/foo.py --incremental --cache-dir /tmp/cachetest/.cache -f json 2>/dev/null >/dev/null; echo "not corrupted json" > /tmp/cachetest/.cache/cache.json; python -m bandit /tmp/cachetest/foo.py --incremental --cache-dir /tmp/cachetest/.cache -f json 2>/tmp/cor_err >/tmp/cor_out; echo "exit=$?"; grep -i corrupted /tmp/cor_err; python -c "import json; d=json.load(open('/tmp/cor_out')); print(d['cache_info'])"
echo "=== no-incremental overrides config ===" && rm -rf /tmp/cachetest/conf_cache && python -m bandit /tmp/cachetest/foo.py -c /tmp/cachetest/bandit.yaml --no-incremental -f json 2>/dev/null >/tmp/ni; python -c "import json; d=json.load(open('/tmp/ni')); print('cache_info', d['cache_info']); print('cache dir exists:', __import__('os').path.isdir('/tmp/cachetest/conf_cache'))"